 pg.evaluate('''()=>{const store=new Map();Object.defineProperty(window,'localStorage',{value:{getItem:k=>store.get(k)||null,setItem:(k,v)=>store.set(k,v)}});const template={id:'property.mediterranean-premium',name:'Mediterranean Premium',templateVersion:'1.4.4-rc.28.1'};const image='data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+lmP8AAAAASUVORK5CYII=';const base={template,createdAt:'2026-11-23T12:00:00Z',updatedAt:'2026-11-25T12:00:00Z',pages:8,languages:3,media:4,readable:true};let items=[{...base,id:'a',root:'D:/WSET/Projects/A',name:'Costa Blanca',websiteName:'Costa Blanca',dashboard:{name:'',customer:'Client A',domain:'example.test'}},{...base,id:'b',root:'D:/WSET/Projects/B',name:'Solmar',websiteName:'Solmar',dashboard:{name:'',customer:'Client B',domain:''},updatedAt:'2026-11-24T12:00:00Z'}];window.setEmpty=()=>{items=[]};window.setMany=()=>{items=Array.from({length:15},(_,i)=>({...base,id:'p'+i,root:'D:/WSET/Projects/P'+i,name:'Project '+i,dashboard:{}}))};for(const p of items){p.lifecycle={status:'not-started',checklist:{},approval:'not-requested',notes:'',dueDate:''};p.progress={done:0,total:9,percent:0,validationCurrent:false};}window.cbpm={lifecycleUpdate:async(id,input)=>{const p=items.find(x=>x.id===id);p.lifecycle={...p.lifecycle,...input};if(input.approval==='approved')p.lifecycle.approvalAt='2026-11-25T12:00:00Z';const values=Object.values(input.checklist);const total=values.filter(x=>x!=='na').length+1+Number(input.approval!=='not-required'),done=values.filter(x=>x==='done').length+Number(!!p.lifecycle.validation?.ok)+Number(input.approval==='approved');p.progress={done,total,percent:Math.round(100*done/total),validationCurrent:!!p.lifecycle.validation};return p.lifecycle},lifecycleValidate:async id=>{const p=items.find(x=>x.id===id);return p.lifecycle.validation={ok:true,errors:0,warnings:1,at:'2026-11-25T12:00:00Z'}},lifecycleHistory:async()=>[{kind:'website',outcome:'failed',at:'2026-11-25T11:00:00Z',counts:{done:1,skipped:3,failed:1,cancelled:0}},{kind:'export',outcome:'completed',at:'2026-11-25T10:00:00Z'}],state:async()=>null,recentProjects:async()=>[],onExportProgress:()=>{},dashboardList:async()=>({items,issues:[],activeRoot:'',dirty:false}),dashboardCovers:async ids=>Object.fromEntries(ids.map(id=>[id,image])),dashboardUpdate:async(id,info)=>{const row=items.find(p=>p.id===id);row.dashboard=info;row.name=info.name||row.websiteName;window.updated=id;return info},dashboardReveal:async id=>{window.revealed=id;return true},openRecent:async root=>{window.opened=root;return null},templateLibraryList:async()=>({items:[],issues:[],root:'D:/WSET/Templates'})};}''')
